                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 4 and 0 <= nc < 4:
                neighbors.append((nr, nc))
    return neighbors

def can_form_word(word):
    word_lower = word.lower()
    for start_r in range(4):
        for start_c in range(4):
            if board[start_r][start_c].lower() != word_lower[0]:
                continue
            # DFS to find the word
            def dfs(r, c, visited, idx):
                if idx == len(word_lower):
                    return True
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in visited and board[nr][nc].lower() == word_lower[idx]:
                        visited.add((nr, nc))
                        if dfs(nr, nc, visited, idx + 1):
                            return True
                        visited.remove((nr, nc))
                return False
            visited = {(start_r, start_c)}
            if dfs(start_r, start_c, visited, 1):
                return True
    return False

